#!/usr/bin/env python3
"""Round 54 (26 September): the Atlas hotspot maps drawn sharp from their PDFs at any zoom. Upload to the culprits repo's patches folder. Safe to run twice."""
import base64, subprocess, sys, os, tempfile
DIFF = base64.b64decode("")
NOTE = """
## Round 54 (26 September): Atlas hotspot plates sharp at any zoom

- atlasVector / atlasPageClip: once the view is closer than the plate's fit
  zoom + 1, the part of the hotspot PDF's first page in view is drawn by
  pdf.js 3.11.174 (cdnjs, loaded on first use) at screen resolution and laid
  as image source "atlas-plate-vector" (blob URL, updateImage) over the
  pictures; the detail squares are hidden while it shows. Falls back to the
  pictures if the PDF or pdf.js cannot be read.
- PDFs copied by culprits-tiles-more scripts/atlas_pdfs.py to atlas/pdfs/
  (the Atlas's server gives no CORS). index.html v=54.
"""
def git(*a):
    return subprocess.run(["git", *a], capture_output=True, text=True)
if not os.path.exists("map/app.js"):
    sys.exit("Run this from the culprits folder.")
with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
    f.write(DIFF); path = f.name
if git("apply", "--check", "-R", path).returncode == 0:
    print("Already applied. Nothing changed.")
else:
    r = git("apply", "--3way", path)
    if r.returncode != 0:
        print(r.stdout + r.stderr)
        git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html")
        sys.exit("Did not apply; nothing changed.")
    print("Code changes applied.")
os.unlink(path)
if os.path.exists("HANDOFF.md"):
    h = open("HANDOFF.md", encoding="utf-8").read()
    if "## Round 54 (26 September)" not in h:
        i = h.index("---") + 3
        open("HANDOFF.md", "w", encoding="utf-8").write(h[:i] + "\n" + NOTE + h[i:])
        print("HANDOFF.md note added.")
